def flatten_lists(values):
    result = []
    for value in values:
        if isinstance(value, list):
            result.extend(flatten_lists(value))
        else:
            result.append(value)
    return result

train-008:
def slugify(text):
    result = []
    pending = False
    for char in text.lower():
        if char.isalnum():
            if pending and result:
                result.append("-")
            result.append(char)
            pending = False
        else:
            pending = True
    return "".join(result)

