def decode_query(query):
    result = {}
    for item in query.split("&"):
        if not item:
            continue
        key, separator, value = item.partition("=")
        key = key.strip()
        if not separator or not key:
            raise ValueError("invalid query item")
        result.setdefault(key, []).append(value)
